ST.xhtml:p:
RY1Trigger(CLK := g_biY1HomeEnable OR bY1HomeEnable);

IF RY1Trigger.Q THEN
    nY1HomeState := 1;
    g_boY1HomeDone := FALSE;
    bY1HomeDone := FALSE;
END_IF;

CASE nY1HomeState OF
  0:
    nY1HomeState := 0;
  1:
    g_Y1Home.Execute := TRUE;
    IF nY1HomingMode = 0 THEN
      g_Y1Home.HomingMode := 0;
      g_Y1Home.Position := dY1HomePosition;
    ELSIF nY1HomingMode = 1 THEN
      g_Y1Home.HomingMode := 5;
      g_Y1Home.Position := 0.0;
    END_IF;
    g_Y1Home.bCalibrationCam := g_bY1AxisZero;
    IF g_Y1Home.Done THEN
      g_Y1Home.Execute := FALSE;
      nY1HomeState := 2;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY1HomeState := 20;
    END_IF;
    IF g_Y1Home.CommandAborted OR g_Y1Home.Error THEN
      g_Y1Home.Execute := FALSE;
      nY1HomeState := 0;
    END_IF;
  2:
    g_Y1MoveAbs.Execute := TRUE;
    g_Y1MoveAbs.Position := dY1HomeOffset;
    g_Y1MoveAbs.Velocity := dY1HomeVel;
    IF g_Y1MoveAbs.Done THEN
      g_Y1MoveAbs.Execute := FALSE;
      bY1HomeDone := TRUE;
      g_boY1HomeDone := TRUE;
      nY1HomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY1HomeState := 21;
    END_IF;
  20:
    g_Y1Home.Execute := FALSE;
    g_Y1MoveStop.Execute := TRUE;
    IF g_Y1MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y1MoveStop.Execute := FALSE;
      nY1HomeState := 1;
    END_IF;
    IF g_Y1MoveStop.CommandAborted OR g_Y1MoveStop.Error THEN
      g_Y1MoveStop.Execute := FALSE;
      nY1HomeState := 0;
    END_IF;
  21:
    g_Y1Home.Execute := FALSE;
    g_Y1MoveStop.Execute := TRUE;
    IF g_Y1MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y1MoveStop.Execute := FALSE;
      nY1HomeState := 2;
    END_IF;
    IF g_Y1MoveStop.CommandAborted OR g_Y1MoveStop.Error THEN
      g_Y1MoveStop.Execute := FALSE;
      nY1HomeState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nY1HomeState := 0;
  g_Y1MoveStop.Execute := FALSE;
  g_Y1Home.Execute := FALSE;
  bY1HomeDone := TRUE;
END_IF;
